static XIDC_OLO: [i32; 12] = [
    13312, 19968, 44032, 77824, 78944, 94208, 131072, 173824, 178208, 183984, 196608, 201552,
];

static XIDC_OHI: [i32; 12] = [
    19903, 42124, 55203, 78895, 82938, 101589, 173791, 178205, 183981, 191456, 201546, 210041,
];

// E1: the mouth is SCALAR-typed. A byte predicate may only be DERIVED from this.

fn xid_start(cp: i32) -> bool {
    let mut a = 0;
    let mut b = 678;
    while a <= b {
        let m = (a + b) / 2;
        let e = XIDS_PK[m as usize];
        let lo = e / 1024;
        if cp < lo { b = m - 1; }
        else if cp > lo + (e % 1024) { a = m + 1; }
        else { return true; }
    }
    let mut k = 0;
    while k < 12 { if cp >= XIDS_OLO[k] && cp <= XIDS_OHI[k] { return true; } k += 1; }
    false
}

fn xid_continue(cp: i32) -> bool {
    let mut a = 0;
    let mut b = 793;
    while a <= b {
        let m = (a + b) / 2;
        let e = XIDC_PK[m as usize];
        let lo = e / 1024;
        if cp < lo { b = m - 1; }
        else if cp > lo + (e % 1024) { a = m + 1; }
        else { return true; }
    }
    let mut k = 0;
    while k < 12 { if cp >= XIDC_OLO[k] && cp <= XIDC_OHI[k] { return true; } k += 1; }
    false
}

// ---- UAX #31 identifier mouth (locales/ucd-identifier-inversion) --------------------------------------------
// E1: classification is a total function on Unicode SCALAR VALUES. The previous predicate was
//   fn is_idc(c: u8) -> bool { ... || c >= 128 }
// which accepted EVERY non-ASCII byte. That was not laziness: in a `u8` the correct predicate is not
// expressible, so `c >= 128` was the only total function available -- a contingent representation choice that
// made the essential constraint unstatable. Measured over-acceptances it allowed: U+00A9 (c), U+2028 LINE
// SEPARATOR, U+3000 ideographic space, and every emoji.
// Invisible to every instrument in this arc, because all of them feed it only VALID programs.
//
// UTF-8 decode. Returns the scalar, or -1 for a malformed or truncated sequence. No slice-of-static is passed
// anywhere here: `&[u8]` params from as_bytes() are fine, but passing `&STATIC` as a slice segfaults (measured).
fn u8at(b: &[u8], i: usize) -> i32 { if i < b.len() { b[i] as i32 } else { -1 } }
fn utf8_len_at(b: &[u8], i: usize) -> usize {
    let c = u8at(b, i);
    if c < 0 { return 0; }
    if c < 128 { return 1; }
    if c >= 194 && c <= 223 { return 2; }
    if c >= 224 && c <= 239 { return 3; }
    if c >= 240 && c <= 244 { return 4; }
    0
}
fn utf8_cont(x: i32) -> bool { x >= 128 && x <= 191 }
fn utf8_scalar_at(b: &[u8], i: usize) -> i32 {
    let n = utf8_len_at(b, i);
    if n == 0 { return -1; }
    let c0 = u8at(b, i);
    if n == 1 { return c0; }
    let c1 = u8at(b, i + 1);
    if !utf8_cont(c1) { return -1; }
    if n == 2 { return (c0 - 192) * 64 + (c1 - 128); }
    let c2 = u8at(b, i + 2);
    if !utf8_cont(c2) { return -1; }
    if n == 3 { return (c0 - 224) * 4096 + (c1 - 128) * 64 + (c2 - 128); }
    let c3 = u8at(b, i + 3);
    if !utf8_cont(c3) { return -1; }
    (c0 - 240) * 262144 + (c1 - 128) * 4096 + (c2 - 128) * 64 + (c3 - 128)
}
// Advance length if b[i..] begins an XID_Continue / XID_Start scalar, else 0. Rust additionally admits `_` as an
// identifier START (it is XID_Continue but not XID_Start), which is why xids_adv tests it separately.
fn xidc_adv(b: &[u8], i: usize) -> usize {
    let cp = utf8_scalar_at(b, i);
    if cp < 0 { return 0; }
    if xid_continue(cp) { return utf8_len_at(b, i); }
    0
}
fn xids_adv(b: &[u8], i: usize) -> usize {
    let cp = utf8_scalar_at(b, i);
    if cp < 0 { return 0; }
    if cp == 95 { return 1; }
    if xid_start(cp) { return utf8_len_at(b, i); }
    0
}
// E4: refuse, do not guess. A malformed UTF-8 sequence where an identifier is being scanned is not a character
// the lexer may silently absorb; rustc rejects such source outright.
fn xid_refuse_malformed(b: &[u8], i: usize) {
    if utf8_scalar_at(b, i) < 0 {
        eprintln!("error: malformed UTF-8 in source at byte offset {}", i);
        std::process::exit(1);
    }
}

fn is_idc(c: u8) -> bool { (c >= 97 && c <= 122) || (c >= 65 && c <= 90) || (c >= 48 && c <= 57) || c == 95 || c >= 128 }   // reduced XID: any UTF-8 non-ASCII byte (>=128) extends an ident (café/naïve/Ωmega/姓名)

// Byte-wise equality of two DYNAMIC strings. The rzrs subset's `==` on String only lowers against a
// compile-time `&'static str` literal (every existing use is `w == "kw"`); comparing two runtime String
// values (the MAC-0 registry lookup) must go through as_bytes(), the lexer's known-good idiom.
// Element-wise copy of a Vec<String>. Whole-Vec `.clone()` is NOT a lowered subset idiom (the only such use
// miscompiled to an empty vec); copying element String clones -- which ARE lowered -- is the safe form.
// CT-118: does this block BIND anything? Measured: 70% of s9_bv blocks and 82% of s9_walk blocks contain no
// `let` at all, so the child env they build is a byte-for-byte copy of the parent that is only ever READ.
// Those copies are 1,135 MB of the 1,914 MB the parser allocates (CT-117). With no `let`, the parent env is
// already exactly the right env -- no copy, no signature change.
fn s9_blk_has_let(b: &Block) -> bool { for st in b.stmts.iter() { match st { Stmt::Let(_p, _t, _i, _e) => { return true; } _ => {} } } false }
fn veccopy(v: &Vec<String>) -> Vec<String> {
    let mut o: Vec<String> = Vec::with_capacity(v.len());
    let mut i = 0;
    while i < v.len() { o.push(v[i].clone()); i = i + 1; }
    o
}
// Split a space-joined token string into its tokens. as_bytes + slice-to_string (the lexer's proven idiom).
fn split_ws(s: &str) -> Vec<String> {
    let bb = s.as_bytes();
    let n = bb.len();
    let mut out: Vec<String> = Vec::new();
    let mut i = 0;
    while i < n {
        while i < n && bb[i] == 32 { i = i + 1; }
        if i >= n { break; }
        let st = i;
        while i < n && bb[i] != 32 { i = i + 1; }
        let sl = &s[st..i];
        out.push(sl.to_string());
    }
    out
}
// Remove a trailing optional-trailing-comma repetition group `$ ( , ) ?` / `$ ( , ) *` from a matcher, so the
// main `$(..)sep*` rep is still recognized (rep_of keys on the last token being */+) and the arm tolerates a
// trailing comma. Only the exact 5-token opt-comma tail is stripped; any other trailing group is left intact.
fn strip_trailing_optcomma(m: &str) -> String {
    let mt = split_ws(m); let n = mt.len();
    if n >= 5 && streq(&mt[n - 5], "$") && streq(&mt[n - 4], "(") && streq(&mt[n - 3], ",") && streq(&mt[n - 2], ")") && (streq(&mt[n - 1], "?") || streq(&mt[n - 1], "*")) {
        let mut out = String::new(); let mut i = 0;
        while i < n - 5 { if out.len() > 0 { out.push(' '); } out.push_str(&mt[i]); i = i + 1; }
        return out;
    }
    m.to_string()
}
// space-join a token slice range [a, b). Used by the multi-metavar repetition binder.
fn mac_join_toks(t: &Vec<String>, a: usize, b: usize) -> String {
    let mut out = String::new(); let mut i = a;
    while i < b && i < t.len() { if out.len() > 0 { out.push(' '); } out.push_str(&t[i]); i = i + 1; }
    out
}
// first index >= from where the token subsequence `sub` occurs in `t`; t.len() if not found (or sub empty).
fn mac_find_subseq(t: &Vec<String>, sub: &Vec<String>, from: usize) -> usize {
    let sn = sub.len(); if sn == 0 { return t.len(); }
    let tn = t.len(); if tn < sn { return tn; }
    let mut i = from;
    while i + sn <= tn {
        let mut j = 0; let mut ok = true;
        while j < sn { if !streq(&t[i + j], &sub[j]) { ok = false; j = sn; } else { j = j + 1; } }
        if ok { return i; }
        i = i + 1;
    }
    tn
}
// Split a space-joined token string on TOP-LEVEL `,` tokens (commas inside ()[]{} do not split), returning the
// balanced parts as re-joined token strings. The MAC-3 multi-metavar separator model.
fn split_commas(s: &str) -> Vec<String> { split_bysep(s, ",") }
// Split a space-joined token string at its FIRST top-level open bracket `op` ("("/"["/"{"), returning
// (tokens before the bracket, tokens strictly inside the balanced bracket group). Used by expand_mixed when a
// mixed matcher's rep group is delimited by a bracket (`$m:ident( $($p),* )`) rather than a flat separator: the
// key's own `name( .. )` group must be matched as a balanced bracket, not split_bysep on "(", or an empty-arg
// call `name()` tears its `)` off into a spurious rep element (extra-`)` miscompile -- derive-where trait_dispatch).
fn s9_split_at_open(s: &str, op: &str) -> (String, String) {
    let cl = if streq(op, "(") { ")" } else if streq(op, "[") { "]" } else { "}" };
    let t = split_ws(s); let n = t.len(); let mut i = 0; let mut d: i64 = 0;
    while i < n {
        if streq(&t[i], "(") || streq(&t[i], "[") || streq(&t[i], "{") { if d == 0 && streq(&t[i], op) { break; } d = d + 1; }
        else if streq(&t[i], ")") || streq(&t[i], "]") || streq(&t[i], "}") { d = d - 1; }
        i = i + 1;
    }
    if i >= n { return (s.to_string(), String::new()); }
    let mut before = String::new(); let mut k = 0;
    while k < i { if before.len() > 0 { before.push(' '); } before.push_str(&t[k]); k = k + 1; }
    // scan the balanced group starting at the open bracket t[i]
    let mut inside = String::new(); let mut dd: i64 = 0; let mut j = i;
    while j < n {
        if streq(&t[j], "(") || streq(&t[j], "[") || streq(&t[j], "{") { dd = dd + 1; if dd == 1 && j == i { j = j + 1; continue; } }
        else if streq(&t[j], ")") || streq(&t[j], "]") || streq(&t[j], "}") { dd = dd - 1; if dd == 0 { let _ = cl; break; } }
        if inside.len() > 0 { inside.push(' '); } inside.push_str(&t[j]); j = j + 1;
    }
    (before, inside)
}
fn s9_ws_empty(s: &str) -> bool { let t = split_ws(s); t.len() == 0 }   // token-empty macro call args -> zero repetition elements
// does the space-joined token string have a `;` at bracket-depth 0? (a multi-statement macro body). Used to wrap
// a stmt-expanding macro's body in `{ .. }` so all statements run, not just the first expr the parser reads.
fn s9_toplevel_semi(s: &str) -> bool {
    let toks = split_ws(s); let mut d: i64 = 0; let mut i = 0;
    while i < toks.len() { let t = &toks[i];
        if streq(t, "(") || streq(t, "[") || streq(t, "{") { d = d + 1; }
        else if streq(t, ")") || streq(t, "]") || streq(t, "}") { d = d - 1; }
        else if streq(t, ";") && d == 0 { return true; }
        i = i + 1; }
    false
}
// Split a space-joined token string on the TOP-LEVEL `sep` token (balanced over ()[]{}), returning the parts as
// re-joined token strings. Empty sep -> one part per top-level token (the empty-separator repetition case).
fn split_bysep(s: &str, sep: &str) -> Vec<String> {
    let toks = split_ws(s);
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut d = 0;
    let mut i = 0;
    let n = toks.len();
    let emptysep = sep.len() == 0;
    while i < n {
        let t = &toks[i];
        let opens = streq(t, "(") || streq(t, "[") || streq(t, "{");
        let closes = streq(t, ")") || streq(t, "]") || streq(t, "}");
        if !emptysep && streq(t, sep) && d == 0 { out.push(cur); cur = String::new(); i = i + 1; continue; }
        if opens { d = d + 1; }
        if closes { d = d - 1; }
        if emptysep && d == 0 && !opens && !closes { out.push(t.to_string()); i = i + 1; continue; }
        if cur.len() > 0 { cur.push(' '); } cur.push_str(t); i = i + 1;
    }
    if !emptysep { out.push(cur); }
    out
}
// Split a `$($t:tt)*` capture into token-trees: each element is ONE token OR ONE balanced group.
// Unlike split_bysep(s,"") (which drops a group entirely -- it accumulates the group tokens into a buffer that the
// emptysep path never flushes), this keeps `( 1 )` as a single element. Used ONLY for the rp=="~" pure-tt-rep path,
// so mac_group_els' split_bysep callers (cfg_if!) are unaffected. Fixes a `$($t:tt)*` capture of a nested macro-call
