        // real first-match semantics. This bypasses arm_ok's LENIENT comma-count heuristic, which rejects the correct
        // tt-muncher arm `$t:ident $punct:tt $($rest)*` (2 prefix metavars, but a comma-less key) -- proc-macro-hack.
        let kt = split_ws(key); let mut j = 0;
        while j < n {
            if streq(&self.mac_names[j], name) {
                let mt = split_ws(&self.mac_matchers[j]);
                let r = self.mac_match_pat(&mt, 0, mt.len(), &kt, 0, kt.len());
                if r == kt.len() as i64 { return j as i64; }
            }
            j = j + 1;
        }
