        if streq(&toks[i], "$") == false || streq(&toks[i + 1], "(") == false { return String::new(); }
        let mut d = 0; let mut k = i + 1; let mut close = 0; let mut got = false;
        while k < n { if streq(&toks[k], "(") { d = d + 1; } if streq(&toks[k], ")") { d = d - 1; if d == 0 { close = k; got = true; k = n; } } if k < n { k = k + 1; } }
        if got == false { return String::new(); }
