                let follow = if mi + adv < mn { mtoks[mi + adv].clone() } else { String::new() };
                let lo = ki;
                if follow.len() > 0 && streq(&follow, "$") == false { let mut d2 = 0; while ki < kn { let t = &ktoks[ki]; if d2 == 0 && streq(t, &follow) { ki = ki; break; } if streq(t, "(") || streq(t, "[") || streq(t, "{") { d2 = d2 + 1; } else if streq(t, ")") || streq(t, "]") || streq(t, "}") { if d2 > 0 { d2 = d2 - 1; } } ki = ki + 1; } } else { if ki < kn { ki = ki + 1; } }   // DEPTH-AWARE: a `$m:expr` value may contain the `follow` literal NESTED (e.g. `$flag:expr` = `(1) | 7` before the closing `)` of `$c($flag:expr)`); stop only at a depth-0 `follow`, else the metavar captured `( 1` and desynced (wasmparser define_wasm_features! bitflag `(1<<5)|Self::X.bits()`). Mirrors mac_match_pat's balanced consumption.
