                let single = streq(&frag, "ident") || streq(&frag, "tt") || streq(&frag, "lifetime") || streq(&frag, "literal") || frag.len() == 0;   /* ONEBIN rung148: `meta` is NOT single-token -- an attr meta can be `path(args)` or `path = lit` (e.g. #[rustc_lint_opt_deny_field_access("..")]); let it fall to the balanced multi-token consume (stops at the `]` follow, tracks paren depth) so `$(#[$attr:meta])*` in top_level_options!/options! matches attr'd fields */
