        if s9_toplevel_semi(&sbody) { let mut wrp = String::from("{ "); wrp.push_str(&sbody); wrp.push_str(" }"); sbody = wrp; }   // multi-statement macro body -> Block expr so ALL statements run. NB: build via push_str, NOT format!("{{ {} }}", sbody) -- SEM0 mis-types the reassigned `sbody` at that {} site and prints its POINTER, wrapping `{ <addr> }` so the statement is dropped (macro_rules_repetition_stmt). [S2 stmt-macro]
        let (bt, bo, idn) = lex(&sbody);
        let mut sub = Parser { idents: idn, toks: bt, offs: bo, pos: 0, no_struct: false, expr_path: false, pending_gt: 0, in_cond: false, expand: true, mac_names: veccopy(&self.mac_names), mac_matchers: veccopy(&self.mac_matchers), mac_bodies: veccopy(&self.mac_bodies), mac_metavars: veccopy(&self.mac_metavars), mac_reps: veccopy(&self.mac_reps), mac_depth: self.mac_depth + 1, rule_toks: Vec::new(), rep_els: Vec::new(), drop_stmt: false, stmt_attrs: Vec::new(), resolve: false, moddir: String::from(""), pend_move: false, pend_async: false, ty_depth: 0 };
