// The finite suffix set. A FLOAT literal admits only f32/f64; an integer literal admits those plus the twelve
// integer suffixes (`1f64` is valid Rust). f16/f128 are feature-gated: rejected UNLESS the crate
// declares the feature (s1_feat_f16/f128) -- rustc's own source enables them (pipeline A).
fn lit_suffix_valid(sfx: &str, is_float: bool) -> bool {
    if sfx.len() == 0 { return true; }
    if streq(sfx, "f32") { return true; }
    if streq(sfx, "f64") { return true; }
    // f16/f128 are rustc-1.95 float types, feature-gated: accepted ONLY when the crate declares
    // `#![feature(f16)]` / `#![feature(f128)]` (pre-scanned by s1_scan_feats at lex start). This admits rustc's
    // own source (core PI/consts use _f128) while keeping D0's stable-oracle rejection of a bare `1.0f16`
    // (D0-02) -- the two oracles are reconciled by modelling the feature gate, not by relaxing the check. [pipeline A]
    if streq(sfx, "f16") { return s1_feat_f16(); }
    if streq(sfx, "f128") { return s1_feat_f128(); }
    if is_float { return false; }
    if streq(sfx, "i8") || streq(sfx, "i16") || streq(sfx, "i32") || streq(sfx, "i64") { return true; }
    if streq(sfx, "i128") || streq(sfx, "isize") { return true; }
    if streq(sfx, "u8") || streq(sfx, "u16") || streq(sfx, "u32") || streq(sfx, "u64") { return true; }
    if streq(sfx, "u128") || streq(sfx, "usize") { return true; }
    false
}
