    if streq(w, "aapcs") || streq(w, "aapcs-unwind") { return true; }
    if streq(w, "avr-interrupt") || streq(w, "avr-non-blocking-interrupt") { return true; }
    if streq(w, "cdecl") || streq(w, "cdecl-unwind") { return true; }
    if streq(w, "cmse-nonsecure-call") || streq(w, "cmse-nonsecure-entry") { return true; }
    if streq(w, "custom") || streq(w, "efiapi") { return true; }
    if streq(w, "fastcall") || streq(w, "fastcall-unwind") { return true; }
    if streq(w, "gpu-kernel") || streq(w, "msp430-interrupt") || streq(w, "ptx-kernel") { return true; }
    if streq(w, "riscv-interrupt-m") || streq(w, "riscv-interrupt-s") { return true; }
    if streq(w, "rust-call") || streq(w, "rust-cold") || streq(w, "rust-invalid") || streq(w, "rust-preserve-none") { return true; }
    if streq(w, "stdcall") || streq(w, "stdcall-unwind") { return true; }
    if streq(w, "system") || streq(w, "system-unwind") { return true; }
    if streq(w, "sysv64") || streq(w, "sysv64-unwind") { return true; }
    if streq(w, "thiscall") || streq(w, "thiscall-unwind") { return true; }
    if streq(w, "unadjusted") { return true; }
    if streq(w, "vectorcall") || streq(w, "vectorcall-unwind") { return true; }
