fn ctor_fn_sig(name: &str) -> String { if streq(name, "String::new") { String::from("fn() -> String {String::new}") } else if streq(name, "String::with_capacity") { String::from("fn(usize) -> String {String::with_capacity}") } else if streq(name, "String::from") { String::from("fn(&str) -> String {<String as From<&str>>::from}") } else if streq(name, "std::process::exit") || streq(name, "process::exit") { String::from("fn(i32) -> ! {exit}") } else { String::from("{unknown}") } }
