fn expr_is_range(e: &ExprK) -> bool { match e { ExprK::Range(_lo, _hi, _inc) => true, _ => false } }
fn slice_result(at: &str) -> String { let base = strip_ref(&strip_elided_lt(at)); let bb = base.as_bytes(); if streq(&base, "str") { String::from("str") } else if streq(&base, "String") { String::from("str") } else if bb.len() > 0 && bb[0] == 91 { format!("[{}]", elem_of(&base)) } else { String::new() } }
