    let pcc = s9_chain_clos_slots(pred, env);
    let idx = s9fresh(); let z = s9const(0); s9emit_setslot(idx, z);
    let found = s9fresh(); let z0 = s9const(0); s9emit_setslot(found, z0);
    let best = s9fresh(); let z1 = s9const(0); s9emit_setslot(best, z1);
