        if bk == 1 { let te = s9op("add8", startp, nb); let c = s9op("lt8", te, endp); let one = s9const(1); let nc = s9op("sub", one, c); let a0 = s9op("mul8", te, c); let a1 = s9op("mul8", endp, nc); endp = s9op("add8", a0, a1); }
        else if bk == 2 { let ns = s9op("add8", startp, nb); let c = s9op("lt8", ns, endp); let one = s9const(1); let nc = s9op("sub", one, c); let a0 = s9op("mul8", ns, c); let a1 = s9op("mul8", endp, nc); startp = s9op("add8", a0, a1); }
