    let m = s9_chain_call1(cc.code, cc.cenv, cp);
    let one = s9const(1); let ns = s9op("sub", one, seen); let sel = s9op("mul", m, ns);
    let one2 = s9const(1); let nsel = s9op("sub", one2, sel);
