// ONEBIN rung169: `src.iter().flat_map(f).take_while(g).collect()` -- flatten each element's f-result, but STOP
// at the first flattened element where g is false (exclude it), ending the WHOLE iteration (take_while). A stop
// flag (loop-carried like esl/ii) gates both loops; when g fails we set stop and skip the push, and the next
// guard check (which ANDs in stop==0) exits inner then outer. pre_configure_attrs uses exactly this chain.
fn s9_vec_flat_map_takewhile_collect(vrecv: &ExprK, flatclos: &ExprK, twclos: &ExprK, env: &S9Env) -> i32 {
    let vbase = s9_zip_base(vrecv, env);
    let it = s9_vec_iter_bounds(vbase);
    let fc = s9_chain_clos_slots(flatclos, env);
    let tw = s9_chain_clos_slots(twclos, env);
    let res = s9_vec_new();
    let stop = s9fresh(); let sz = s9const(0); s9emit_setslot(stop, sz);
    let esl = s9fresh(); s9emit_setslot(esl, it.dptr);
    s9emit_loop_open();
    { let lt = s9op("lt8", esl, it.end); let z = s9const(0); let ns = s9op("eq", stop, z); let g = s9op("mul", lt, ns); s9emit_brz(g); }
    let ev = s9_slot_load(esl, 0);
    let inner = s9_chain_call1(fc.code, fc.cenv, ev);
    let ilen = s9_load_at(inner, 0); let idp = s9_slot_load(inner, 8);
    let ii = s9fresh(); let z1 = s9const(0); s9emit_setslot(ii, z1);
    s9emit_loop_open();
    { let ilt = s9op("lt", ii, ilen); let z = s9const(0); let ns2 = s9op("eq", stop, z); let g2 = s9op("mul", ilt, ns2); s9emit_brz(g2); }
    let e8 = s9const(8); let ioff = s9op("mul", ii, e8); let iaddr = s9op("add8", idp, ioff); let vv = s9_slot_load(iaddr, 0);
    let cond = s9_chain_call1(tw.code, tw.cenv, vv);
    s9emit_brz(cond); s9_vec_push1(res, vv); s9emit_pool();   // g true -> keep
    { let z = s9const(0); let nc = s9op("eq", cond, z); s9emit_brz(nc); let one = s9const(1); s9emit_setslot(stop, one); s9emit_pool(); }   // g false -> set stop (take_while ends)
    s9emit_cont(); s9emit_incr(ii); s9emit_jmpend();
    s9emit_cont(); s9emit_incr4(esl); s9emit_jmpend();
    res
}
// does the flat_map closure body return a Range (`|&x| (a..b)`)? -> use the range-variant. (&ExprK: &Box coerces.) [SA5]
fn s9_expr_is_range(e: &ExprK) -> bool { match e { ExprK::Range(_l, _h, _i) => true, ExprK::Paren(x) => s9_expr_is_range(x), _ => false } }
fn s9_expr_is_stringy(e: &ExprK) -> bool { match e { ExprK::MacCall(mp, _d, _t) => streq(&dump_path(mp), "format"), ExprK::Method(_r, m, _t2, _a) => streq(m, "to_string") || streq(m, "to_owned") || streq(m, "to_uppercase") || streq(m, "to_lowercase"), ExprK::Call(c, _a) => { let cn = s9_callee_name(c); streq(&cn, "String::from") || streq(&cn, "String::new") }, ExprK::Block(bl) => { let mut r = false; for st in bl.stmts.iter() { match st { Stmt::Expr(e) => { r = s9_expr_is_stringy(e); } _ => {} } } r }, ExprK::Paren(x) => s9_expr_is_stringy(x), _ => false } }
fn s9_clos_returns_string(clos: &ExprK) -> bool { match clos { ExprK::Closure(_m, _p, _r, body) => s9_expr_is_stringy(body), _ => false } }
fn s9_clos_returns_range(clos: &ExprK) -> bool { match clos { ExprK::Closure(_m, _p, _r, body) => s9_expr_is_range(body), _ => false } }
fn s9_expr_is_charish(e: &ExprK) -> bool {
    match e {
        ExprK::Char(_c) => true,
        ExprK::Method(_r, m, _t, a) => a.len() == 0 && (streq(m, "to_ascii_uppercase") || streq(m, "to_ascii_lowercase")),   // char->char (to_uppercase/to_lowercase return ITERATORS, not char)
        ExprK::Paren(inr) => s9_expr_is_charish(inr),
        ExprK::Block(b) => { let mut r = false; for st in b.stmts.iter() { match st { Stmt::Expr(x) => { r = s9_expr_is_charish(x); } _ => {} } } r },
        ExprK::If(_c, t, els) => { let mut r = false; for st in t.stmts.iter() { match st { Stmt::Expr(x) => { r = s9_expr_is_charish(x); } _ => {} } } if r { for x in els.iter() { if s9_expr_is_charish(x) == false { r = false; } } } r },
        _ => false
    }
}
fn s9_clos_returns_char(clos: &ExprK) -> bool { match clos { ExprK::Closure(_m, _p, _r, body) => s9_expr_is_charish(body), _ => false } }
