    let nv = s9expr(narg, env);
    let cc = s9_chain_clos_slots(clos, env);
    let res = if tk == 6 { s9_vec_new() } else { 0 };
    let acc = s9fresh(); let z = s9const(0); s9emit_setslot(acc, z);
    let isl = s9fresh(); let z1 = s9const(0); s9emit_setslot(isl, z1);
    s9emit_loop_open();
