    let e8 = s9const(8); let off = s9op("mul", isl, e8); let dptr = s9op("add8", dp, off);
    let hdr = s9_alloc(16); s9_store_at(hdr, 0, nv); let zc = s9const(0); s9_store_at(hdr, 4, zc); s9_slot_store(hdr, 8, dptr);
    let yv = s9_chain_call1(cc.code, cc.cenv, hdr);
    if tk == 6 { s9_vec_push1(res, yv); } else { let na = s9op("add", acc, yv); s9emit_setslot(acc, na); }
    s9emit_cont(); s9emit_incr(isl); s9emit_jmpend();
