// `s.char_indices().zip(vec).map(|((i,c),(r,_))| ..).collect()`: walk the string and `vec` in lockstep, build the
// nested pair ((byte_off,char),(vec[i])), call the map closure with it, push the result. Length = min(chars, vec.len).
// Only the char_indices-on-the-left shape (the snippet input_vec builder) is recognised.
fn s9_charidx_zip_map_collect(cb: i32, vec_arg: &ExprK, clos: &ExprK, env: &S9Env) -> i32 {
    let cc = s9_chain_clos_slots(clos, env);
    let vbase = s9_zip_base(vec_arg, env);
    let vlen = s9_load_at(vbase, 0); let vdp = s9_slot_load(vbase, 8);
    let out = s9_vec_new();
    let isl = s9fresh(); let zi = s9const(0); s9emit_setslot(isl, zi);
    s9emit_loop_open();
    let pos = s9_load_at(cb, 16); let clen0 = s9_load_at(cb, 8);
    let g1 = s9op("lt", pos, clen0); let g2 = s9op("lt", isl, vlen); let g = s9op("and", g1, g2); s9emit_brz(g);
    let dp = s9_slot_load(cb, 0); let a0 = s9op("add8", dp, pos); let b0 = s9_loadb(a0);
    let packed = s9_utf8_decode(dp, pos, b0);
    let mask = s9const(16777215); let cp = s9op("and", packed, mask);
    let inner_ic = s9_charidx_tuple(pos, cp);
    let e8 = s9const(8); let voff = s9op("mul", isl, e8); let va = s9op("add8", vdp, voff); let rc = s9_slot_load(va, 0);
    let outer = s9_alloc(16); s9_slot_store(outer, 0, inner_ic); s9_slot_store(outer, 8, rc);
    let mapped = s9_chain_call1(cc.code, cc.cenv, outer);
    let s24 = s9const(24); let clen = s9op("shu8", packed, s24); let np = s9op("add", pos, clen); s9_store_at(cb, 16, np);
    s9_vec_push1(out, mapped);
    s9emit_cont(); s9emit_incr(isl); s9emit_jmpend();
    out
}
