// bare `x.iter().zip(y.iter()).collect::<Vec<(A,B)>>()` (NO map): build a Vec of 16-byte (a[i],b[i]) pair cells,
// lockstep to min(len). Mirrors s9_pair_map_collect but pushes the pair cell directly (identity). Peels cloned/copied
// off each arm (so `a.iter().cloned().zip(b.iter().cloned())` resolves to the two Vec bases).
fn s9_pair_collect(abase: i32, bbase: i32, env: &S9Env) -> i32 {
    let alen = s9_load_at(abase, 0); let adp = s9_slot_load(abase, 8);
    let blen = s9_load_at(bbase, 0); let bdp = s9_slot_load(bbase, 8);
    let lt = s9op("lt8", alen, blen); let one = s9const(1); let nlt = s9op("sub", one, lt); let m0 = s9op("mul8", alen, lt); let m1 = s9op("mul8", blen, nlt); let len = s9op("add8", m0, m1);
    let out = s9_vec_new();
    let isl = s9fresh(); let zi = s9const(0); s9emit_setslot(isl, zi);
    s9emit_loop_open();
    let g = s9op("lt", isl, len); s9emit_brz(g);
    let e8 = s9const(8); let off = s9op("mul", isl, e8);
    let xa = s9op("add8", adp, off); let xv = s9_slot_load(xa, 0);
    let yb = s9op("add8", bdp, off); let yv = s9_slot_load(yb, 0);
    let pair = s9_alloc(16); s9_slot_store(pair, 0, xv); s9_slot_store(pair, 8, yv);
    s9_vec_push1(out, pair);
    s9emit_cont(); s9emit_incr(isl); s9emit_jmpend();
    out
}
