fn s9_ref_target_name(e: &ExprK) -> String {
    match e {
        ExprK::Ref(_m, inner) => s9_bare_name(inner),
        ExprK::RawRef(_m, inner) => s9_bare_name(inner),
        ExprK::Path(p) => dump_path(p),
        _ => String::from(""),
    }
}
