fn s9_cell_base(recv: &ExprK, env: &S9Env) -> i32 { let b = s9expr(recv, env); let t = s9_recv_vty(env, recv); if s9_ty_is_ref(&t) { let d = s9fresh(); println!("  v{}: i64 = load8 v{}", d, b); d } else { b } }
