    let hlen = s9_load_at(vr, 0);
    let hp0 = s9_slot_load(vr, 8);
    let nlen = s9_load_at(vn, 0);
    let np = s9_slot_load(vn, 8);
    let rv = s9fresh();
    let lbl = s9_lbl();
    let bad = s9op("gt", nlen, hlen);
    s9emit_brz(bad);
    let z = s9const(0);
    s9emit_then_tail(rv, lbl, z);
    let hp = if is_end { let off = s9op("sub", hlen, nlen); s9op("add", hp0, off) } else { hp0 };
    let eq = s9call3("__streq_at", hp, np, nlen);
    s9emit_else_tail(rv, lbl, eq);
    rv
