    let dp = s9_slot_load(base, 8);
    let removed = s9_slot_load(dp, 0);
    let one = s9const(1); let j = s9fresh(); s9emit_setslot(j, one);
    s9emit_loop_open();
    let g = s9op("lt", j, len); s9emit_brz(g);
    let e = s9const(8); let joff = s9op("mul", j, e); let jaddr = s9op("add8", dp, joff);
    let jv = s9_slot_load(jaddr, 0);
    let jm1 = s9op("sub", j, one); let doff = s9op("mul", jm1, e); let daddr = s9op("add8", dp, doff);
    println!("  store8 v{} v{}", daddr, jv);
