    while i + 7 <= n { if streq(&vty[i..(i+7)], "Ty Dyn(") { st = (i as i32) + 7; i = n; } i += 1; }
    if st < 0 { return String::new(); }
    let mut j = st as usize; let mut e = j;
    while j < n { let c = b[j]; if c == 41 || c == 32 || c == 43 { e = j; j = n; } else { e = j + 1; } j += 1; }
