    if (streq(nm, "__vec_alias_s") || streq(nm, "__vec_alias_i")) && args.len() == 1 { let src = s9expr(&args[0], env); let h = s9_alloc(16); let l = s9_load_at(src, 0); s9_store_at(h, 0, l); let c = s9_load_at(src, 4); s9_store_at(h, 4, c); let d = s9_slot_load(src, 8); s9_slot_store(h, 8, d); return h; }
