    let etystr = if ib.refty != 0 { if streq(&es, "Vec") || es.len() == 0 { String::from("Ty Ref") } else { format!("Ty Ref(Ty Path {})", es) } } else { String::from("iterscalar") };
    let nm = s9_patname(pat);
    let benv = s9_env_push1(env, nm, ib.slot, etystr);
