    let g = s9op("lt8", esl, it.end); s9emit_brz(g);
    let ev = s9_slot_load(esl, 0);
    let xv = s9_chain_call1(cc.code, cc.cenv, ev); s9emit_setslot(xsl, xv);
    s9_walk(body, &benv);
    s9emit_cont();
    s9emit_incr4(esl);
    s9emit_jmpend();
