fn s9_for_chunks(pat: &Pat, recv: &ExprK, narg: &ExprK, body: &Block, env: &S9Env, exact: bool) -> i32 {
    let vbase = s9_iter_srcbase(recv, env);
    let len = s9_load_at(vbase, 0); let dp = s9_slot_load(vbase, 8);
    let nv = s9expr(narg, env);
    let vty = s9_recv_vty(env, recv);
    let wsl = s9fresh(); let z0 = s9const(0); s9emit_setslot(wsl, z0);
    let isl = s9fresh(); let z1 = s9const(0); s9emit_setslot(isl, z1);
    let nm = s9_patname(pat);
    let benv = s9_env_push1(env, nm, wsl, vty);
    s9emit_loop_open();
    let g = if exact { let e2 = s9op("add8", isl, nv); let lp1 = s9op("add8", len, s9const(1)); s9op("lt8", e2, lp1) } else { s9op("lt", isl, len) };
    s9emit_brz(g);
    // chunk len: exact = nv (no partial); else min(nv, len-isl) branchlessly
    let rem = s9op("sub", len, isl); let lt = s9op("lt8", rem, nv); let one = s9const(1); let nlt = s9op("sub", one, lt);
    let a0 = s9op("mul8", rem, lt); let a1 = s9op("mul8", nv, nlt); let cmin = s9op("add8", a0, a1);
    let clen = if exact { nv } else { cmin };
    let e8 = s9const(8); let off = s9op("mul", isl, e8); let dptr = s9op("add8", dp, off);
    let hdr = s9_alloc(16); s9_store_at(hdr, 0, clen); let zc = s9const(0); s9_store_at(hdr, 4, zc); s9_slot_store(hdr, 8, dptr);
    s9emit_setslot(wsl, hdr);
    s9_walk(body, &benv);
    s9emit_cont();
    let ni = s9op("add8", isl, nv); s9emit_setslot(isl, ni);
    s9emit_jmpend();
    s9const(0)
}
// `for c in v.rchunks(n)`: chunks from the END. chunk_end walks len -> 0; each chunk is [cend-clen, cend) with
// clen = min(n, cend) (the LEFTMOST chunk may be shorter). Mirror of s9_for_chunks, backward.
fn s9_for_rchunks(pat: &Pat, recv: &ExprK, narg: &ExprK, body: &Block, env: &S9Env) -> i32 {
    let vbase = s9_iter_srcbase(recv, env);
    let len = s9_load_at(vbase, 0); let dp = s9_slot_load(vbase, 8);
    let nv = s9expr(narg, env);
    let vty = s9_recv_vty(env, recv);
    let wsl = s9fresh(); let z0 = s9const(0); s9emit_setslot(wsl, z0);
    let cend = s9fresh(); s9emit_setslot(cend, len);
    let nm = s9_patname(pat);
    let benv = s9_env_push1(env, nm, wsl, vty);
    s9emit_loop_open();
    let zc = s9const(0); let g = s9op("lt8", zc, cend); s9emit_brz(g);
    let lt = s9op("lt8", cend, nv); let one = s9const(1); let nlt = s9op("sub", one, lt);
    let a0 = s9op("mul8", cend, lt); let a1 = s9op("mul8", nv, nlt); let clen = s9op("add8", a0, a1);
    let cs = s9op("sub8", cend, clen);
    let e8 = s9const(8); let off = s9op("mul8", cs, e8); let dptr = s9op("add8", dp, off);
    let hdr = s9_alloc(16); s9_store_at(hdr, 0, clen); let z2 = s9const(0); s9_store_at(hdr, 4, z2); s9_slot_store(hdr, 8, dptr);
    s9emit_setslot(wsl, hdr);
    s9_walk(body, &benv);
    s9emit_cont();
    s9emit_setslot(cend, cs);
    s9emit_jmpend();
    s9const(0)
}
// SHRINK: iterate a materialized Vec<&str> (split/rsplit/split_whitespace/lines all shared this tail).
