    let icnt = s9fresh(); let z = s9const(0); s9emit_setslot(icnt, z);
    let islot = s9fresh(); let z2 = s9const(0); s9emit_setslot(islot, z2);
    let mut bn: Vec<String> = veccopy(&env.names); bn.push(iname);
    let mut bs: Vec<i32> = veccopy_i32(&env.slots); bs.push(islot);
    let mut bt: Vec<String> = veccopy(&env.types); bt.push(format!("Ty Path {}", ity));
    let benv = S9Env { names: bn, slots: bs, fnames: veccopy(&env.fnames), foffs: veccopy_i32(&env.foffs), ftypes: veccopy(&env.ftypes), frets_name: veccopy(&env.frets_name), frets_ty: veccopy(&env.frets_ty), types: bt };
