    let mut bn: Vec<String> = veccopy(&env.names); bn.push(iname); bn.push(xname);
    let mut bs: Vec<i32> = veccopy_i32(&env.slots); bs.push(islot); bs.push(ib.slot);
    let mut bt: Vec<String> = veccopy(&env.types); bt.push(format!("Ty Path {}", ity)); bt.push(xty);
    let benv = S9Env { names: bn, slots: bs, fnames: veccopy(&env.fnames), foffs: veccopy_i32(&env.foffs), ftypes: veccopy(&env.ftypes), frets_name: veccopy(&env.frets_name), frets_ty: veccopy(&env.frets_ty), types: bt };
    s9emit_loop_open();
