fn s9_iter_is_byte(vty: &str) -> bool { if streq(vty, "bytes") { return true; } if str_contains(vty, "Slice(Ty Path u8)") { return true; } let e = index_elem(vty); streq(&e, "u8") }   // RP-STD-BYTEITER: a &[u8]/Vec<u8> element is 1 byte -> byte-load + stride-1 iteration
