    if b[0] != 92 { return b[0] as i64; }
    if b.len() < 2 { return 92; }
    let e = b[1];
    if e == 110 { return 10; }
    if e == 116 { return 9; }
    if e == 114 { return 13; }
    if e == 48 { return 0; }
    if e == 92 { return 92; }
    if e == 39 { return 39; }
    if e == 34 { return 34; }
    if e == 120 { if b.len() >= 4 { return s9_hexval(b[2]) * 16 + s9_hexval(b[3]); } return 0; }
    if e == 117 { let mut v = 0; let mut i = 3; while i < b.len() { if b[i] == 125 { i = b.len(); } else { v = v * 16 + s9_hexval(b[i]); i = i + 1; } } return v; }
