// builds a negative bound as Unary(Neg, Lit) -- it says so at the construction site -- and s9_char_val
// already decodes a char literal including its escapes.
fn s9_litexpr_val(e: &ExprK) -> i32 { match e { ExprK::LitInt(n) => lit_value(*n) as i32, ExprK::Bool(b) => { if *b { 1 } else { 0 } }, ExprK::Char(cv) => s9_char_val(cv) as i32, ExprK::Unary(op, inner) => { if streq(op, "Neg") { 0 - s9_litexpr_val(inner) } else { 0 } }, _ => 0 } }
