// the i-th param name of a const fn ("" if out of range).
fn s9_const_fn_pname(params: &Vec<Param>, i: i32) -> String { let mut k = 0; let mut r = String::new(); for pp in params.iter() { if k == i { r = format!("{}", pp.name); } k += 1; } r }
