fn s9_const_ref_evalable(items: &Vec<Item>, name: &str) -> bool {
    for it in items.iter() { if streq(&it.ident, name) { match &it.kind { ItemKind::Const(_t, rhs) => { match rhs { Some(e) => { return s9_const_evalable(items, e); }, None => {} } }, _ => {} } } }
    false
}
fn s9_const_eval(items: &Vec<Item>, e: &ExprK) -> i64 { s9_const_eval1(items, e, "", 0, "", 0) }
