fn s9_box_struct_inner(env: &S9Env, ft: &str) -> String {
    // if ft is a bare Box<STRUCT>/P<STRUCT> field type, return the inner struct name (via last "Ty Path"), else "".
    if s9_bare_box_ty(ft) == false { return String::new(); }
    let inner = s9_struct_of_ty(ft);
    if inner.len() > 0 { if s9_field_has(env, &format!("$nflds#{}", inner)) { return inner; } }
    String::new()
}
fn s9_variant_field_ty_adj(env: &S9Env, vname: &str, i: i32) -> String {
    // like s9_variant_field_ty, but a Box<STRUCT> field records its STRIPPED inner struct type ("Ty Path <S>"),
    // so a single-loaded (kind-0) box-struct payload binding is byte-identical to a non-box struct payload:
    // both field-access (s9_recv_struct) and method-call (the Box<..>&&!boxpay deref at ~7202) treat `a` as the
    // struct ADDRESS directly. Reconciles the box-struct blocker with the dev's method-receiver convention.
    let ft = s9_variant_field_ty(env, vname, i);
    let inn = s9_box_struct_inner(env, &ft);
    if inn.len() > 0 { format!("Ty Path {}", inn) } else { ft }
}
fn s9_adjust_box_flags(env: &S9Env, pat: &Pat, fl: String) -> String {
    let vn = s9_pat_vqual(pat); if vn.len() == 0 { return fl; }
    let bb = fl.as_bytes(); let mut r = String::new(); let mut i = 0;
    while (i as usize) < bb.len() { let c = bb[i as usize];
        if c == 50 { let ft = s9_variant_field_ty_adj(env, &vn, i); if s9_box_struct_inner(env, &ft).len() > 0 { r.push('0'); } else { r.push('2'); } }
        else if c == 48 { r.push('0'); } else if c == 49 { r.push('1'); } else if c == 51 { r.push('3'); } else { r.push('0'); }
        i += 1; }
    r
}
