        if info.n4.len() > 0 { names.push(format!("{}", info.n4)); slots.push(if info.pst == 1 { s9_fld_load2(bbase, info.p4, info.q4) } else { s9_bind_slot(bbase, arefm, boff + 32, info.s4) }); btypes.push(s9_bind_ty_ref(info.s4, s9_variant_field_ty_adj(env, &vn, 4), arefm, info.pst)); }
        if info.n5.len() > 0 { names.push(format!("{}", info.n5)); slots.push(if info.pst == 1 { s9_fld_load2(bbase, info.p5, info.q5) } else { s9_bind_slot(bbase, arefm, boff + 40, info.s5) }); btypes.push(s9_bind_ty_ref(info.s5, s9_variant_field_ty_adj(env, &vn, 5), arefm, info.pst)); }
        if info.pst == 1 && info.n6.len() > 0 { names.push(format!("{}", info.n6)); slots.push(s9_fld_load2(bbase, info.p6, info.q6)); btypes.push(String::new()); }
        if info.pst == 1 && info.n7.len() > 0 { names.push(format!("{}", info.n7)); slots.push(s9_fld_load2(bbase, info.p7, info.q7)); btypes.push(String::new()); }
        if info.pst == 1 && info.n8.len() > 0 { names.push(format!("{}", info.n8)); slots.push(s9_fld_load2(bbase, info.p8, info.q8)); btypes.push(String::new()); }
        if info.pst == 1 && info.n9.len() > 0 { names.push(format!("{}", info.n9)); slots.push(s9_fld_load2(bbase, info.p9, info.q9)); btypes.push(String::new()); }
        if info.pst == 1 && info.n10.len() > 0 { names.push(format!("{}", info.n10)); slots.push(s9_fld_load2(bbase, info.p10, info.q10)); btypes.push(String::new()); }
        if info.pst == 1 && info.n11.len() > 0 { names.push(format!("{}", info.n11)); slots.push(s9_fld_load2(bbase, info.p11, info.q11)); btypes.push(String::new()); }
