fn s9_sconst_build(enc: &str) -> i32 { let toks = split_ws(enc); if toks.len() < 2 { return s9const(0); } let sz = str_to_i64(&toks[1]); let base = s9_alloc(sz as i32); let mut i = 2; while i + 1 < toks.len() { let off = str_to_i64(&toks[i]) as i32; let val = str_to_i64(&toks[i+1]); let cv = s9const(val); s9_slot_store(base, off, cv); i += 2; } base }
fn s9_sconst_encode(items: &Vec<Item>, e: &ExprK) -> String { match e { ExprK::Struct(sp, fields, _b) => { let sn = path_base(&dump_path(sp)); let sz = s9_struct_nfields(items, &sn) * 8; let mut r = format!("SC {}", sz); for f in fields.iter() { let off = s9_struct_field_off_decl(items, &sn, &f.name); if off >= 0 { let v = s9_const_eval(items, &f.expr); r = format!("{} {} {}", r, off, v); } } r } _ => String::from("") } }
fn s9_sconst_size(items: &Vec<Item>, e: &ExprK) -> i64 { match e { ExprK::Struct(sp, _f, _b) => { let sn = path_base(&dump_path(sp)); s9_struct_nfields(items, &sn) * 8 } _ => 0 - 1 } }
