fn s9_struct_field_off_decl(items: &Vec<Item>, tn: &str, fname: &str) -> i64 { for it in items.iter() { if streq(&it.ident, tn) { match &it.kind { ItemKind::Struct(_g, fields) => { let mut i: i64 = 0; for f in fields.iter() { if streq(&f.ident, fname) { return i * 8; } i += 1; } } _ => {} } } } 0 - 1 }
fn s9_struct_nfields(items: &Vec<Item>, tn: &str) -> i64 { for it in items.iter() { if streq(&it.ident, tn) { match &it.kind { ItemKind::Struct(_g, fields) => { let mut i: i64 = 0; for _f in fields.iter() { i += 1; } return i; } _ => {} } } } 0 }
fn s9_strip_crate_segs(nm: &str) -> String { let mut cur = format!("{}", nm); let mut go = true; while go { let fs = first_seg2(&cur); if fs.len() == 0 { go = false; } else { let fb = fs.as_bytes(); if fb[0] >= 97 && fb[0] <= 122 { cur = s9_after_first_seg(&cur); } else { go = false; } } } cur }
fn s9_const_struct_ok(items: &Vec<Item>, e: &ExprK) -> bool { match e { ExprK::Struct(_p, fields, base) => { match base { Some(_b) => { return false; } None => {} } if fields.len() == 0 { return false; } for f in fields.iter() { if s9_const_evalable(items, &f.expr) == false { return false; } } true } _ => false } }
