    // dup method to `u32::encode` (the dup-qualified name the impl emitted), which the bare name would dangle past.
    match recv { ExprK::Path(rp) => { let rn = dump_path(rp); let ck = format!("$iterconc#{}", rn); if s9_field_has(env, &ck) { let cc = s9_field_type(env, &ck); let q = format!("{}::{}", cc, name); if s9_fn_is_known(env, &q) { return q; } } } _ => {} }
