    let newdp = s9op("add8", sdp, si);
    let hdr = s9_alloc(16);
    s9_store_at(hdr, 0, newlen);
    let z1 = s9const(0); s9_store_at(hdr, 4, z1);
    s9_slot_store(hdr, 8, newdp);
