fn s9_is_strvec_call(e: &ExprK) -> bool { match e { ExprK::Method(_r, m, _t, _a) => streq(m, "lines") || streq(m, "split") || streq(m, "splitn") || streq(m, "rsplit") || streq(m, "split_whitespace") || streq(m, "matches"), _ => false } }
