    let one = s9const(1); let li = s9op("sub", len, one); let dp = s9_slot_load(vec, 8); let e8 = s9const(8); let off = s9op("mul8", li, e8); let addr = s9op("add8", dp, off); let elem = s9_slot_load(addr, 0);
