    let inw = s9fresh(); let z0 = s9const(0); s9emit_setslot(inw, z0);
    let wstart = s9fresh(); let z1 = s9const(0); s9emit_setslot(wstart, z1);
    let i = s9fresh(); let z2 = s9const(0); s9emit_setslot(i, z2);
    s9emit_loop_open();
    let g = s9op("lt", i, slen); s9emit_brz(g);
    let baddr = s9op("add8", sdp, i); let b = s9_loadb(baddr);
    let c32 = s9const(32); let is32 = s9op("eq", b, c32);
    let c9 = s9const(9); let ge9 = s9op("ge", b, c9); let c13 = s9const(13); let le13 = s9op("le", b, c13); let ctrl = s9op("and", ge9, le13);
    let isws = s9op("or", is32, ctrl);
