    let flen = s9op("sub", slen2, wstart); let fdp = s9op("add8", sdp2, wstart);
    let fhdr = s9_alloc(16); s9_store_at(fhdr, 0, flen); let zc2 = s9const(0); s9_store_at(fhdr, 4, zc2); s9_slot_store(fhdr, 8, fdp);
