fn s9_is_vec_eq_expr(env: &S9Env, e: &ExprK) -> bool { let it = s9_init_ty(env, e); let vt = s9_recv_vty(env, e); s9_ty_is_vec(&it) || s9_ty_is_vec(&vt) }
