                   let key = format!("$dbg#{}", nm);
                   let ty = s9_lookup_type(env, &key);
                   { let ntt = s9_lookup_type(env, &nm); if s9_dbg_pfx(&ntt, "Ty Tup(") { let inner = format!("{}", &ntt[7..]); if str_contains(&inner, "Ty Tup(") || str_contains(&inner, "Ty Array(") || str_contains(&inner, "Vec<") { let tv = s9expr(e, env); s9_dbg_tupfield(tv, &ntt, env); return true; } } }   // named tuple with a NESTED tuple/array/Vec element: the $dbg flat-kind channel can't carry sub-structure, so recurse by the recorded TYPE via s9_dbg_tupfield
                   let ta = s9_dbg_arity(&ty, "dbgtup ");
