fn s9_mac_is_noop_log(p: &Path) -> bool {
    let n = dump_path(p);
    streq(&n, "trace") || streq(&n, "debug") || streq(&n, "info") || streq(&n, "warn") || streq(&n, "error")
}
fn s9_mac_args_are_exprs(p: &Path) -> bool {
    let n = dump_path(p);
    if streq(&n, "println") { return true; } if streq(&n, "print") { return true; }
    if streq(&n, "eprintln") { return true; } if streq(&n, "eprint") { return true; }
    if streq(&n, "format") { return true; } if streq(&n, "assert") { return true; }
    if streq(&n, "vec") { return true; }
    if superset_on() && (streq(&n, "assert_eq") || streq(&n, "assert_ne")) { return true; }   // ONEBIN driver D2 rung189: assert_eq!(a,b)/assert_ne! args are two exprs (comma-split, reparsed+scanned like assert!/matches!), so an assert_eq!-bodied closure is liftable, not opaque. THE create_and_enter_global_ctxt enter closure (`|tcx| { let feed=tcx.create_crate_num(..).unwrap(); assert_eq!(feed.key(), LOCAL_CRATE); ..; f(tcx); tcx.finish() }` -- the COMPILE-CALLBACK wrapper) was opaque solely on its assert_eq! -> s9expr returned const 0 -> gcx.enter(f=null) -> the run thunk invoked a null/garbage closure (code 0x6f) -> SEGV, so the compile callback (and tcx.analysis) never ran. superset-gated -> //@S9 byte-identical (self-host keeps the old whitelist).
    if streq(&n, "matches") { return true; }   // matches!(scrut, PAT): scrut is an expr (free-var scannable); the PAT reparses to a Path/Struct whose only scan-visible names are the (uppercase, skipped) variant + field values -- so a `matches!`-bodied closure IS liftable, not opaque. Unblocks `find(|k| matches!(k, Enum::V))`.
    false
}
fn s9_env_add_names(base: &S9Env, ns: &Vec<String>) -> S9Env {
    let mut names = veccopy(&base.names); let mut slots = veccopy_i32(&base.slots); let mut types = veccopy(&base.types);
    for n in ns.iter() { names.push(format!("{}", n)); slots.push(0); types.push(String::new()); }
    S9Env { names: names, slots: slots, fnames: __vec_alias_s(&base.fnames), foffs: __vec_alias_i(&base.foffs), ftypes: __vec_alias_s(&base.ftypes), frets_name: __vec_alias_s(&base.frets_name), frets_ty: __vec_alias_s(&base.frets_ty), types: types }
}
// IE-ITER: register a single ($key -> $val) fact into the field registry, returning the extended env. Used to
// thread a map/filter closure's iterator ELEMENT TYPE from the call site down to the lifted closure's param
// typing (keyed by the closure hash), so `foos().iter().map(|f| f.val())` types `f` to the element struct and
// `f.val()` qualifies to the dep crate's `Foo::val` instead of a bare (unresolvable cross-crate) `call val`.
fn s9_env_add_fact(base: &S9Env, key: &str, val: &str) -> S9Env {
    let mut fnm = veccopy(&base.fnames); let mut fof = veccopy_i32(&base.foffs); let mut fty = veccopy(&base.ftypes);
    fnm.push(format!("{}", key)); fof.push(0); fty.push(format!("{}", val));
    S9Env { names: __vec_alias_s(&base.names), slots: __vec_alias_i(&base.slots), fnames: fnm, foffs: fof, ftypes: fty, frets_name: __vec_alias_s(&base.frets_name), frets_ty: __vec_alias_s(&base.frets_ty), types: __vec_alias_s(&base.types) }
}
fn s9_is_byref_iter_recv(recv: &ExprK) -> bool { match recv { ExprK::Method(_rr, rn, _rt2, ra) => (streq(rn, "iter") || streq(rn, "rev")) && ra.len() == 0, _ => false } }
