    unsafe { S9NC = 0; }
    s9ck_reset();
    println!("fn __fnthunk_{}", nm);
    let ev = s9fresh(); println!("  v{}: i32 = param", ev);
    let mut slots: Vec<i32> = Vec::new();
    let mut i = 0;
    while i < n { let sl = s9fresh(); println!("  v{}: i32 = param", sl); slots.push(sl); i += 1; }
    let r = s9fresh();
    let mut suf = String::new();
    for sl in slots.iter() { suf.push_str(&format!(" v{}", sl)); }
